      "decisive_negative_evidence": [
        {
          "evidence_id": "E0045",
          "explanation": "Xi's loyalist-stacked third-term outcome indicates a power-consolidation pattern that cuts against open, independent scrutiny."
        },
        {
          "evidence_id": "E0067",
          "explanation": "The new leadership team is explicitly described as loyalists, which weakens the clean-competence reading."
        }
      ],
      "inherited_baseline_and_constraints": "China's closed political environment makes silence less informative, so country opacity is not used as proof of integrity. The score turns on the limited but real evidence of anti-conflict rules versus loyalist consolidation and the lack of direct personal-benefit proof.",
      "ruler_attribution": "Strong on system design and personnel power, weak on direct personal enrichment or direct correction evidence. The record supports a controlled, loyalist-centered governing style more than a personal-extraction finding.",
      "supported_lenses": [
